<script setup lang="ts">
import {usePage} from '@inertiajs/vue3';import {money} from '../lib/format';
defineProps<{events:any[]}>();
const page=usePage<any>();
function timestamp(value:string){return new Date(value).toLocaleString('en-US',{timeZone:page.props.auth?.timezone||'UTC',dateStyle:'medium',timeStyle:'short'});}
function value(field:string,entry:any):string{if(entry===null||entry===undefined||entry==='')return '—';if(Array.isArray(entry))return entry.map(e=>value(field.replace(/s$/,''),e)).join(', ')||'None';if(typeof entry==='boolean')return entry?'Yes':'No';if(field.endsWith('_cents'))return money(entry);if(['account_id','usual_paying_account_id'].includes(field))return page.props.catalog?.accounts?.find((a:any)=>a.id===entry)?.name||'Deleted account';if(['member_id','recipient_id'].includes(field))return page.props.catalog?.members?.find((m:any)=>m.id===entry)?.nickname||'Former member';if(['category_id','parent_id','replacement_id'].includes(field)){const c=page.props.catalog?.categories?.find((c:any)=>c.id===entry);const p=page.props.catalog?.categories?.find((p:any)=>p.id===c?.parent_id);return c?(p?p.name+' › ':'')+c.name:'Deleted category';}if(field.endsWith('_id'))return 'Linked record';return typeof entry==='object'?'Updated values':String(entry).replaceAll('_',' ');}
function changes(event:any){return event.display_changes||Object.entries(event.changes||{}).filter(([key])=>key!=='id'&&!key.startsWith('provider_')&&!['generation_key','rule_snapshot','payload','reminder_version'].includes(key)).map(([key,entry]:any)=>({field:key.replace('_cents','').replaceAll('_',' '),old:value(key,entry?.old),new:value(key,entry?.new)}));}
</script>
<template><div class="flex flex-col divide-y divide-line"><p class="help pb-2">Times shown in {{page.props.auth?.timezone||'UTC'}}.</p><div v-for="event in events" :key="event.id||event.created_at" class="py-3"><div class="flex flex-wrap justify-between gap-3"><span class="font-medium">{{event.action.replaceAll('_',' ')}}</span><time :datetime="event.created_at" class="text-xs text-muted">{{timestamp(event.created_at)}}</time></div><p class="mt-1 text-xs text-muted">{{event.actor_name}}</p><dl v-if="changes(event).length" class="mt-3 grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 rounded-md bg-zinc-50 p-3 text-xs"><template v-for="change in changes(event)" :key="change.field"><dt class="text-muted capitalize">{{change.field}}</dt><dd class="break-words"><span>{{change.old}}</span><span aria-label="changed to" class="mx-2">→</span><span class="font-medium">{{change.new}}</span></dd></template></dl></div><p v-if="!events.length" class="help py-6">No changes recorded yet.</p></div></template>
